// lesson23 ch04: init() は main より先に走る
package main

import "fmt"

var config string

// init はパッケージ読み込み時に自動で呼ばれます（自分では呼ばない）
func init() {
	config = "日本語モード"
	fmt.Println("init: 設定を初期化しました")
}

func main() {
	// この時点で config は init によって設定済みです
	fmt.Println("main: 設定 =", config)
}

exercise.starter:
package main

import (
	"bufio"
	"fmt"
	"os"
)

// ここに「設定を読み込みました」と出力する init() を書く

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()

	// ここから下を書く: ようこそ、<名前> さん と出力する
	_ = name
	_ = fmt.Println
}

exercise.answer:
// lesson23 ch04 解答
package main

import (
	"bufio"
	"fmt"
	"os"
)

// init は main より先に自動実行されます。呼び出しコードは書きません。
// Python でモジュールのトップレベルに書いた処理が import 時に走るのと
// 同じ役割を、Go では init という関数の形で担います。
func init() {
	fmt.Println("設定を読み込みました")
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()
	fmt.Println("ようこそ、" + name + " さん")
}
